  render: () => {
    const [text, setText] = useState('');
    const maxLength = 200;
    return <div style={{
      width: '400px'
    }}>
        <InputGroup>
          <InputGroupTextarea placeholder="Enter your message..." value={text} onChange={e => {
          setText(e.target.value);
        }} maxLength={maxLength} aria-label="Message" />
          <InputGroupAddon align="block-end">
            <span className="mdt-text-xs">
              {text.length}/{maxLength} characters
            </span>
          </InputGroupAddon>
        </InputGroup>
      </div>;
  }
